function createFileTypeIcon(
	Icon: ComponentType<{ 'aria-hidden'?: boolean | 'false' | 'true'; className?: string }>,
	colorClassName: string,
): ComponentType<FileManagerFileTypeIconProps> {
	return function FileTypeIcon({ className }) {
		return <Icon aria-hidden='true' className={cn('shrink-0', colorClassName, className)} />;
	};
}

function mimeTypeFrom(values: Readonly<Record<string, string>>, fallback: string) {
	return (file: Readonly<FileManagerFileTypeMatchInput>) => values[file.extension] ?? fallback;
}

import type {
	FileManagerFileTypeDefinition,
	FileManagerRegistry,
} from '@components/file-type-registry/file-manager-file-type-types';
import { getFileManager } from './file-manager-registry';
import type { FileViewerFileDescriptor, FileViewerKind } from './file-viewer-types';

export type FileViewerKindInput = Pick<FileViewerFileDescriptor, 'mimeType' | 'name' | 'path'>;

export function getFileViewerExtension(value: string): string {
	const clean = value.split(/[?#]/, 1)[0].replaceAll('\\', '/');
	const name = clean.slice(clean.lastIndexOf('/') + 1);
	const dot = name.lastIndexOf('.');
	return dot > 0 && dot < name.length - 1 ? name.slice(dot + 1).toLowerCase() : '';
}

export function getFileSystemViewerExtension(value: string): string {
	const clean = value.replaceAll('\\', '/').replace(/\/+$/, '');
	const name = clean.slice(clean.lastIndexOf('/') + 1);
	const dot = name.lastIndexOf('.');
	return dot > 0 && dot < name.length - 1 ? name.slice(dot + 1).toLowerCase() : '';
}

export function normalizeFileViewerMimeType(mimeType: string | undefined): string {
	return mimeType?.split(';', 1)[0].trim().toLowerCase() ?? '';
}

export function resolveFileViewerKind(
	input: FileViewerKindInput | string,
	mimeType?: string,
	manager: FileManagerRegistry = getFileManager(),
): FileViewerKind {
	const file = typeof input === 'string' ? { name: input, mimeType } : input;
	return toFileViewerKind(resolveFileViewerType(file, manager));
}

export function resolveFileSystemViewerKind(
	input: FileViewerKindInput,
	manager: FileManagerRegistry = getFileManager(),
): FileViewerKind {
	return toFileViewerKind(resolveFileSystemViewerType(input, manager));
}

export function resolveFileViewerType(
	file: FileViewerKindInput,
	manager: FileManagerRegistry = getFileManager(),
): FileManagerFileTypeDefinition | undefined {
	return manager.fileTypes.resolve({
		...file,
		extension: getFileViewerExtension(file.name || file.path || ''),
		kind: 'file',
	});
}

export function resolveFileSystemViewerType(
	file: FileViewerKindInput,
	manager: FileManagerRegistry = getFileManager(),
): FileManagerFileTypeDefinition | undefined {
	return manager.fileTypes.resolve({
		...file,
		extension: getFileSystemViewerExtension(file.name || file.path || ''),
		kind: 'file',
	});
}

export function getFileViewerMimeType(
	file: FileViewerKindInput,
	kind = resolveFileViewerKind(file),
	manager: FileManagerRegistry = getFileManager(),
): string {
	return resolveMimeType(file, kind, manager, getFileViewerExtension(file.name || file.path || ''));
}

export function getFileTypeMimeType(
	file: FileViewerKindInput,
	definition: FileManagerFileTypeDefinition,
	kind = toFileViewerKind(definition),
	manager: FileManagerRegistry = getFileManager(),
): string {
	const normalized = normalizeFileViewerMimeType(file.mimeType);
	if (normalized) return normalized;
	const value = file.name || file.path || '';
	const urlExtension = getFileViewerExtension(value);
	const rawExtension = getFileSystemViewerExtension(value);
	const extension = definition.match.extensions?.includes(rawExtension) ? rawExtension : urlExtension;
	const input = manager.fileTypes.resolveInput({ ...file, extension, kind: 'file' });
	let mimeType: string | undefined;
	try {
		mimeType = typeof definition.mimeType === 'function' ? definition.mimeType(input) : definition.mimeType;
	} catch {
		// Consumer MIME resolvers fail closed to the viewer-kind fallback.
	}
	return normalizeFileViewerMimeType(mimeType) || defaultFileViewerMimeType(kind);
}

export function getFileSystemViewerMimeType(
	file: FileViewerKindInput,
	kind = resolveFileSystemViewerKind(file),
	manager: FileManagerRegistry = getFileManager(),
): string {
	return resolveMimeType(file, kind, manager, getFileSystemViewerExtension(file.name || file.path || ''));
}

export function defaultFileViewerMimeType(kind: FileViewerKind): string {
	return {
		audio: 'audio/mpeg',
		image: 'image/*',
		pdf: 'application/pdf',
		text: 'text/plain',
		unsupported: 'application/octet-stream',
		video: 'video/mp4',
	}[kind];
}

export function toFileViewerKind(definition: FileManagerFileTypeDefinition | undefined): FileViewerKind {
	return definition?.viewerKind ?? 'unsupported';
}

function resolveMimeType(
	file: FileViewerKindInput,
	kind: FileViewerKind,
	manager: FileManagerRegistry,
	extension: string,
): string {
	const normalized = normalizeFileViewerMimeType(file.mimeType);
	if (normalized) return normalized;
	const input = { ...file, extension, kind: 'file' as const };
	const definition = manager.fileTypes.resolve(input);
	if (definition?.viewerKind === kind)
		return manager.fileTypes.resolveMimeType(input) ?? defaultFileViewerMimeType(kind);
	return defaultFileViewerMimeType(kind);
}

'use client';

import { useEffect, useState } from 'react';
import type { FileViewerBytes } from './file-viewer-types';

type ObjectUrlState = {
	bytes: FileViewerBytes;
	mimeType: string;
	url: string;
};

export function useFileViewerObjectUrl(bytes: FileViewerBytes | undefined, mimeType: string): string | undefined {
	const [state, setState] = useState<ObjectUrlState>();

	useEffect(() => {
		if (!bytes || typeof Blob === 'undefined' || typeof URL === 'undefined' || !URL.createObjectURL) {
			setState(undefined);
			return;
		}
		const url = URL.createObjectURL(new Blob([copyFileViewerBytes(bytes)], { type: mimeType }));
		setState({ bytes, mimeType, url });
		return () => URL.revokeObjectURL(url);
	}, [bytes, mimeType]);

	return state && state.bytes === bytes && state.mimeType === mimeType ? state.url : undefined;
}

export function copyFileViewerBytes(bytes: FileViewerBytes): ArrayBuffer {
	if (bytes instanceof Uint8Array) return bytes.slice().buffer;
	return bytes.slice(0);
}

'use client';

import { AlertCircle, LoaderCircle, Pencil, Save, X } from 'lucide-react';
import type { ComponentPropsWithRef, KeyboardEvent, ReactNode } from 'react';
import { useEffect, useRef, useState } from 'react';
import { cn } from '@/lib/utils';
import type { FileViewerFileDescriptor, FileViewerMessages } from './file-viewer-types';
import { mergeFileViewerMessages } from './file-viewer-types';

export type TextFileViewerProps = Omit<ComponentPropsWithRef<'section'>, 'children' | 'onChange'> & {
	file: FileViewerFileDescriptor;
	text: string;
	draft?: string;
	editing?: boolean;
	defaultEditing?: boolean;
	error?: ReactNode;
	messages?: Partial<FileViewerMessages>;
	onDraftChange?: (draft: string) => void;
	onEditingChange?: (editing: boolean) => void;
	onSave?: (draft: string) => Promise<void> | void;
	pending?: boolean;
	readOnly?: boolean;
	showHeader?: boolean;
	textareaProps?: Omit<ComponentPropsWithRef<'textarea'>, 'children' | 'defaultValue' | 'onChange' | 'value'>;
};

export function TextFileViewer({
	className,
	defaultEditing = false,
	draft: controlledDraft,
	editing: controlledEditing,
	error,
	file,
	messages: messageOverrides,
	onDraftChange,
	onEditingChange,
	onSave,
	pending = false,
	readOnly = false,
	showHeader = true,
	text,
	textareaProps,
	...props
}: TextFileViewerProps) {
	const messages = mergeFileViewerMessages(messageOverrides);
	const [internalDraft, setInternalDraft] = useState(text);
	const [internalEditing, setInternalEditing] = useState(defaultEditing);
	const [internalPending, setInternalPending] = useState(false);
	const [internalError, setInternalError] = useState<ReactNode>();
	const previousText = useRef(text);
	const draft = controlledDraft ?? internalDraft;
	const editing = !readOnly && (controlledEditing ?? internalEditing);
	const saving = pending || internalPending;
	const dirty = isTextFileViewerDirty(text, draft);
	const canEdit = !readOnly && Boolean(onSave || onDraftChange || controlledDraft !== undefined);

	const changeDraft = (nextDraft: string) => {
		if (controlledDraft === undefined) setInternalDraft(nextDraft);
		onDraftChange?.(nextDraft);
		setInternalError(undefined);
	};
	const changeEditing = (nextEditing: boolean) => {
		if (controlledEditing === undefined) setInternalEditing(nextEditing);
		onEditingChange?.(nextEditing);
	};

	useEffect(() => {
		if (previousText.current === text) return;
		const wasDirty = draft !== previousText.current;
		previousText.current = text;
		if (!editing || !wasDirty) changeDraft(text);
	}, [draft, editing, text]);

	const cancel = () => {
		if (saving) return;
		changeDraft(text);
		changeEditing(false);
	};
	const save = async () => {
		if (!onSave || !dirty || saving) return;
		setInternalPending(true);
		setInternalError(undefined);
		try {
			await onSave(draft);
			changeEditing(false);
		} catch (saveError) {
			setInternalError(messages.saveFailed(saveError));
		} finally {
			setInternalPending(false);
		}
	};
	const handleSaveShortcut = (event: KeyboardEvent<HTMLTextAreaElement>) => {
		textareaProps?.onKeyDown?.(event);
		if (event.defaultPrevented || !onSave || !(event.metaKey || event.ctrlKey) || event.key.toLowerCase() !== 's')
			return;
		event.preventDefault();
		void save();
	};
	const effectiveError = internalError ?? error;

	return (
		<section
			data-slot='text-file-viewer'
			data-dirty={dirty || undefined}
			data-editing={editing || undefined}
			className={cn('bg-base-100 flex min-h-64 min-w-0 flex-col', !showHeader && 'relative', className)}
			{...props}
		>
			{showHeader ? (
				<div className='border-base-300 flex min-h-10 shrink-0 items-center gap-2 border-b px-2 py-1.5'>
					<div className='min-w-0 flex-1 truncate text-xs font-medium'>{file.name}</div>
					{readOnly ? <span className='badge badge-ghost badge-sm'>{messages.readOnly}</span> : null}
					{editing ? (
						<div
							role='toolbar'
							aria-label={messages.editingActionsLabel(file)}
							className='flex shrink-0 items-center gap-1'
						>
							<button type='button' className='btn btn-ghost btn-sm' disabled={saving} onClick={cancel}>
								<X aria-hidden='true' className='size-4' />
								{messages.cancel}
							</button>
							{onSave ? (
								<button
									type='button'
									className='btn btn-primary btn-sm'
									disabled={!dirty || saving}
									aria-busy={saving || undefined}
									onClick={() => void save()}
								>
									{saving ? (
										<LoaderCircle aria-hidden='true' className='size-4 animate-spin' />
									) : (
										<Save aria-hidden='true' className='size-4' />
									)}
									{saving ? messages.saving : messages.save}
								</button>
							) : null}
						</div>
					) : canEdit ? (
						<button
							type='button'
							aria-label={messages.editFileLabel(file)}
							title={messages.editFileLabel(file)}
							className='btn btn-ghost btn-sm'
							disabled={saving}
							onClick={() => changeEditing(true)}
						>
							<Pencil aria-hidden='true' className='size-4' />
							{messages.edit}
						</button>
					) : null}
				</div>
			) : editing ? (
				<div
					role='toolbar'
					aria-label={messages.editingActionsLabel(file)}
					className='border-base-300 flex min-h-10 shrink-0 items-center justify-end gap-1 border-b px-2 py-1.5'
				>
					<button type='button' className='btn btn-ghost btn-sm' disabled={saving} onClick={cancel}>
						<X aria-hidden='true' className='size-4' />
						{messages.cancel}
					</button>
					{onSave ? (
						<button
							type='button'
							className='btn btn-primary btn-sm'
							disabled={!dirty || saving}
							aria-busy={saving || undefined}
							onClick={() => void save()}
						>
							{saving ? (
								<LoaderCircle aria-hidden='true' className='size-4 animate-spin' />
							) : (
