		imageProps?.onLoad?.(event);
	};
	const handleError = (event: SyntheticEvent<HTMLImageElement>) => {
		setFailedSrc(src);
		imageProps?.onError?.(event);
	};
	return (
		<figure
			data-slot='image-file-viewer'
			className={cn('bg-base-200 flex min-h-64 min-w-0 flex-col', className)}
